<template>
  <div class="selected-videos">
    <div class="columns is-multiline">
      <div v-for="(video, index) in selectedVideos" :key="index" 
           class="video-container column is-4">
        <VideoPlayer
          :video="video"
          :index="index"
          v-if="!video.watched"
          @video-watched="markVideoAsWatched"
        />
      </div>
    </div>
  </div>
</template>

<script>
import VideoPlayer from "@/components/VideoPlayer.vue";

export default {
  name: "SelectedVideos",
  props: {
    selectedVideos: {
      type: Array,
      required: true,
    },
  },
  components: {
    VideoPlayer
  },
  methods: {
    markVideoAsWatched(video) {
      // Find the video in the array and mark it as watched
      const index = this.selectedVideos.findIndex(v => v === video);
      if (index !== -1) {
        this.selectedVideos[index].watched = true;
      }
    }
  }
};
</script>

<style scoped>
.selected-videos {
  text-align: center;
  padding: 2rem;
}

.video-container {
  margin: 1rem 0;
}
</style>